// ── Kahn's Algorithm (BFS-based Topological Sort) — O(V + E) ──
// graph: adjacency list object { node: [neighbors...] }
function kahnTopologicalSort(graph) {
  const nodes = Object.keys(graph);
  const inDegree = {};

  // Step 1: initialise all in-degrees to 0
  for (const node of nodes) inDegree[node] = 0;

  // Step 2: count actual incoming edges
  for (const node of nodes) {
    for (const neighbor of graph[node]) {
      // neighbor may not be a key if it has no outgoing edges
      if (!(neighbor in inDegree)) inDegree[neighbor] = 0;
      inDegree[neighbor]++;
    }
  }

  // Step 3: seed queue with all zero-in-degree vertices
  const queue = nodes.filter(n => inDegree[n] === 0);
  const order = [];

  // Step 4: BFS-style processing
  while (queue.length > 0) {
    const u = queue.shift();   // dequeue
    order.push(u);             // add to topological order

    for (const v of graph[u]) {
      inDegree[v]--;           // remove the u->v constraint
      if (inDegree[v] === 0) {
        queue.push(v);         // v's prerequisites all met
      }
    }
  }

  // Step 5: cycle check — did we process every vertex?
  if (order.length !== Object.keys(inDegree).length) {
    return { order: null, hasCycle: true };
  }
  return { order, hasCycle: false };
}

// Course prerequisite graph: key must be taken before values
const courses = {
  "Calculus":     ["Linear Algebra"],
  "Linear Algebra": ["Algorithms"],
  "Intro CS":     ["Data Structures", "Algorithms"],
  "Data Structures": ["Algorithms"],
  "Algorithms":   []
};

const { order, hasCycle } = kahnTopologicalSort(courses);
console.log(order);
// One valid output: ['Calculus', 'Intro CS', 'Linear Algebra',
//                   'Data Structures', 'Algorithms']
console.log(hasCycle); // false

// Cycle example: A requires B, B requires C, C requires A
const cyclic = { A: ["B"], B: ["C"], C: ["A"] };
console.log(kahnTopologicalSort(cyclic).hasCycle); // true

// ── DFS-Based Topological Sort — O(V + E) ─────────────────────
function dfsTopologicalSort(graph) {
  const WHITE = 0, GREY = 1, BLACK = 2;
  const color = {};
  const stack = [];
  let hasCycle = false;

  // Initialise all vertices as unvisited
  for (const node of Object.keys(graph)) color[node] = WHITE;

  function dfs(u) {
    if (hasCycle) return;   // short-circuit once cycle found
    color[u] = GREY;        // mark as 'in current recursion stack'

    for (const v of graph[u]) {
      if (color[v] === GREY) {
        // Back edge: v is an ancestor on the current stack
        hasCycle = true;
        return;
      }
      if (color[v] === WHITE) {
        dfs(v);             // explore unvisited neighbor
      }
      // BLACK: v already fully processed, skip
    }

    color[u] = BLACK;   // all successors explored
    stack.push(u);      // post-order: push AFTER exploring all successors
  }

  // Run DFS from every unvisited vertex (handles disconnected graphs)
  for (const node of Object.keys(graph)) {
    if (color[node] === WHITE) dfs(node);
  }

  if (hasCycle) return { order: null, hasCycle: true };

  // Stack contains vertices in reverse topological order
  stack.reverse();
  return { order: stack, hasCycle: false };
}

// Same course graph
const courses = {
  "Calculus":        ["Linear Algebra"],
  "Linear Algebra":  ["Algorithms"],
  "Intro CS":        ["Data Structures", "Algorithms"],
  "Data Structures": ["Algorithms"],
  "Algorithms":      []
};

const { order } = dfsTopologicalSort(courses);
console.log(order);
// ['Calculus', 'Linear Algebra', 'Intro CS', 'Data Structures', 'Algorithms']
// (exact order depends on DFS traversal path)

// Verify the ordering
function verifyTopologicalOrder(graph, order) {
  const position = {};
  order.forEach((node, i) => position[node] = i);
  for (const [u, neighbors] of Object.entries(graph)) {
    for (const v of neighbors) {
      if (position[u] > position[v]) {
        return `INVALID: ${u} appears after ${v} but ${u}->${v} edge exists`;
      }
    }
  }
  return 'VALID';
}

console.log(verifyTopologicalOrder(courses, order)); // 'VALID'
